9	// Escape-equivalence regression for manifest batch ids: a JSON escape —
10	// including a UTF-16 surrogate pair — names the same character as the one
11	// written directly, so respelling a batch id never creates a second batch.
12	// Hex letter case and direct/escaped mixing are spelling choices, not
13	// identity, and a literal backslash in the decoded text is ordinary text
14	// that no escape decoding may merge with the character an escape names.
15	
16	// bs is one backslash. The manifests below build their escape text out of
17	// it, so escCJK below is the twelve ASCII characters of two JSON unicode
18	// escapes (backslash, u, 6, 2, 7, 9, backslash, u, 6, b, 2, 1) — the JSON
19	// parser is what decodes them into the two CJK characters.
20	const bs = "\\"
21	
22	var (
23		// escCJK spells 批次-1 with both CJK characters escaped.
24		escCJK = bs + "u6279" + bs + "u6b21" + "-1"
25		// escMixed spells 批次-1 with 批 written directly and 次 escaped.
26		escMixed = "批" + bs + "u6b21" + "-1"
27		// escNew spells 批次-新 fully escaped.
28		escNew = bs + "u6279" + bs + "u6b21" + "-" + bs + "u65b0"
29		// esc10000 and esc10FFFF are the surrogate-pair spellings of the two
30		// boundary characters a UTF-16 pair can express.
31		esc10000  = bs + "ud800" + bs + "udc00" // U+10000
32		esc10FFFF = bs + "udbff" + bs + "udfff" // U+10FFFF
33		// escEmoji spells 😀 (U+1F600) as a surrogate pair; escEmojiMixedHex
34		// is the same pair with the hex letter case varied.
35		escEmoji         = bs + "ud83d" + bs + "ude00"
36		escEmojiMixedHex = bs + "uD83d" + bs + "uDE00"
37		// escFFFD spells a genuine U+FFFD replacement character as an escape.
38		escFFFD = bs + "ufffd"
39		// escLiteralBackslashID spells, in JSON, an id whose decoded text is
40		// the twelve literal characters backslash-u-d-8-3-d-backslash-u-d-e-0-0:
41		// each backslash is itself escaped in the JSON source.
42		escLiteralBackslashID = bs + bs + "ud83d" + bs + bs + "ude00"
43		// literalBackslashID is what escLiteralBackslashID decodes to.
44		literalBackslashID = bs + "ud83d" + bs + "ude00"
45	)
46	
47	// TestParseManifestEscapeSpellingsDecodeToSameIDs feeds one manifest whose
48	// batch ids are spelled every legal way — directly, as BMP escapes, as
49	// surrogate pairs at both boundaries (U+10000 and U+10FFFF), with mixed
50	// hex letter case and mixed direct/escaped characters — and requires every
51	// spelling of one id to decode to the very same text.
52	func TestParseManifestEscapeSpellingsDecodeToSameIDs(t *testing.T) {
53		manifest := `[
54			{"batch":"批次-1","product":"P","quantity":1,"unit":"kg"},
55			{"batch":"` + escCJK + `","product":"P","quantity":1,"unit":"kg"},
56			{"batch":"` + escMixed + `","product":"P","quantity":1,"unit":"kg"},
57			{"batch":"` + "\U00010000" + `","product":"P","quantity":1,"unit":"kg"},
58			{"batch":"` + esc10000 + `","product":"P","quantity":1,"unit":"kg"},
59			{"batch":"` + "\U0010FFFF" + `","product":"P","quantity":1,"unit":"kg"},
60			{"batch":"` + esc10FFFF + `","product":"P","quantity":1,"unit":"kg"},
61			{"batch":"😀","product":"P","quantity":1,"unit":"kg"},
62			{"batch":"` + escEmojiMixedHex + `","product":"P","quantity":1,"unit":"kg"}
63		]`
64		inputs, err := ParseManifest([]byte(manifest))
65		if err != nil {
66			t.Fatalf("every spelling is legal JSON text: %v", err)
67		}
68		want := []string{
