84	// TestImportEscapedRespellingConfirmsStoredIDs registers ids written
85	// directly, then re-submits them escaped: each one is a duplicate
86	// confirmation of the stored record and the registry gains nothing.
87	func TestImportEscapedRespellingConfirmsStoredIDs(t *testing.T) {
