131	// TestImportNewEscapedIDCreatedOnce introduces a new id twice in one
132	// manifest — first written directly, then respelled with escapes — so only
133	// the first occurrence creates a record and the respelling confirms it.
134	func TestImportNewEscapedIDCreatedOnce(t *testing.T) {
