247	// TestParseManifestRejectsLoneSurrogateShapes covers every malformed
248	// surrogate shape: a lone high or low surrogate, a reversed pair, a high
249	// surrogate followed by a plain character, and two high surrogates. Each
250	// fails the manifest at the record's 1-based position naming the batch
251	// field — never substituted with U+FFFD and registered, and never cited
252	// back as an undecodable id — even when a legal record precedes it.
253	func TestParseManifestRejectsLoneSurrogateShapes(t *testing.T) {
254		cases := map[string]string{
