256			"lone low surrogate":               "B" + bs + "ude00",
257			"reversed surrogate pair":          "B" + bs + "ude00" + bs + "ud83d",
258			"high surrogate then plain letter": "B" + bs + "ud83d" + "X",
259			"two high surrogates":              "B" + bs + "ud83d" + bs + "ud83d",
