13	// This file guards the two batch commands when --registry names a symbolic
14	// link: a registration or import that adds batches must save into the file
15	// the link points at — the link stays a link to the same target, the target
16	// keeps its permissions, and both paths read the same records — while a link
17	// whose target cannot be resolved rejects the command without creating the
18	// target or touching the link.
19	
20	// assertStillSymlink fails unless path is still a symbolic link storing
21	// exactly wantTarget.
22	func assertStillSymlink(t *testing.T, path, wantTarget string) {
23		t.Helper()
24		info, err := os.Lstat(path)
25		if err != nil {
26			t.Fatalf("the link must still exist: %v", err)
27		}
28		if info.Mode()&os.ModeSymlink == 0 {
29			t.Fatalf("%s must still be a symbolic link, got mode %v", path, info.Mode())
30		}
31		target, err := os.Readlink(path)
32		if err != nil {
33			t.Fatal(err)
34		}
35		if target != wantTarget {
36			t.Fatalf("link target = %q, want unchanged %q", target, wantTarget)
37		}
38	}
39	
40	// setupLinkedCLIRegistry writes content to targetPath with the given
41	// permissions and points a symbolic link at it, returning the link path.
42	func setupLinkedCLIRegistry(t *testing.T, targetPath, linkPath, linkTarget, content string, mode os.FileMode) {
43		t.Helper()
44		writeFile(t, targetPath, content)
45		if err := os.Chmod(targetPath, mode); err != nil {
46			t.Fatal(err)
47		}
48		if err := os.MkdirAll(filepath.Dir(linkPath), 0o755); err != nil {
49			t.Fatal(err)
50		}
51		if err := os.Symlink(linkTarget, linkPath); err != nil {
52			t.Fatal(err)
53		}
54	}
55	
56	// Registering a new batch through a link appends it to the linked registry:
57	// the target file gains the record after the existing ones, the link is
58	// still a link to the same target, the target keeps its permissions, and
59	// reading back through either path sees the same two batches.
60	func TestBatchRegisterThroughSymlinkSavesToTarget(t *testing.T) {
61		cases := []struct {
62			name       string
63			linkPath   func(root string) string
64			linkTarget func(root, targetPath string) string
65		}{
66			{
67				"absolute target",
68				func(root string) string { return filepath.Join(root, "link.json") },
69				func(root, targetPath string) string { return targetPath },
70			},
71			{
72				"relative target, link in another directory",
73				func(root string) string { return filepath.Join(root, "links", "link.json") },
74				func(root, targetPath string) string { return filepath.Join("..", "real.json") },
75			},
76		}
77		for _, tc := range cases {
78			t.Run(tc.name, func(t *testing.T) {
79				root := t.TempDir()
80				targetPath := filepath.Join(root, "real.json")
81				linkPath := tc.linkPath(root)
82				linkTarget := tc.linkTarget(root, targetPath)
83				setupLinkedCLIRegistry(t, targetPath, linkPath, linkTarget,
84					`{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`, 0o640)
85	
86				var stdout bytes.Buffer
87				err := runBatchRegister([]string{
88					"--registry", linkPath,
89					"--batch", "NEW-1", "--product", "P-9", "--quantity", "5", "--unit", "box",
90				}, &stdout)
91				if err != nil {
92					t.Fatalf("registering through the link must succeed: %v", err)
93				}
94				var out struct {
95					Batch  string `json:"batch"`
96					Status string `json:"status"`
97				}
98				if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
99					t.Fatalf("stdout is not the expected JSON: %v (%q)", err, stdout.String())
100				}
101				if out.Batch != "NEW-1" || out.Status != "created" {
102					t.Fatalf("stdout = %+v, want batch NEW-1 status created", out)
103				}
104	
105				assertStillSymlink(t, linkPath, linkTarget)
106				info, err := os.Stat(targetPath)
107				if err != nil {
108					t.Fatal(err)
109				}
110				if info.Mode().Perm() != 0o640 {
111					t.Fatalf("target permissions = %v, want preserved 0640", info.Mode().Perm())
112				}
113	
114				// The full result — old record first, new record appended — is
115				// visible through the link path and the real path alike.
116				for _, path := range []string{linkPath, targetPath} {
117					data, err := os.ReadFile(path)
118					if err != nil {
119						t.Fatal(err)
120					}
121					var stored struct {
122						Version int `json:"version"`
123						Batches []struct {
124							Batch string `json:"batch"`
125						} `json:"batches"`
126					}
127					if err := json.Unmarshal(data, &stored); err != nil {
128						t.Fatalf("registry read via %s is not valid JSON: %v", path, err)
129					}
130					if stored.Version != 1 || len(stored.Batches) != 2 ||
131						stored.Batches[0].Batch != "OLD" || stored.Batches[1].Batch != "NEW-1" {
132						t.Fatalf("registry read via %s = %s, want OLD then NEW-1", path, data)
133					}
134				}
135			})
136		}
137	}
138	
139	// Importing through a link saves every new batch into the linked registry
140	// and reports the per-record statuses on stdout exactly as for a direct
141	// path.
142	func TestBatchImportThroughSymlinkSavesToTarget(t *testing.T) {
143		root := t.TempDir()
144		targetPath := filepath.Join(root, "real.json")
145		linkPath := filepath.Join(root, "link.json")
146		setupLinkedCLIRegistry(t, targetPath, linkPath, targetPath,
147			`{"version":1,"batches":[{"batch":"B1","product":"P-7","quantity":120,"unit":"kg"}]}`, 0o644)
