149		writeFile(t, manifest, `[
150	  {"batch": "B1", "product": "P-7", "quantity": 120, "unit": "kg"},
151	  {"batch": "B2", "product": "P-8", "quantity": 1, "unit": "box"}
152	]`)
153	
154		var stdout bytes.Buffer
155		if err := runBatchImport([]string{"--registry", linkPath, "--input", manifest}, &stdout); err != nil {
156			t.Fatalf("importing through the link must succeed: %v", err)
157		}
158		var out importOutput
159		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
160			t.Fatalf("stdout is not the expected JSON: %v (%q)", err, stdout.String())
161		}
162		if len(out.Results) != 2 || out.Results[0].Status != "duplicate" || out.Results[1].Status != "created" {
163			t.Fatalf("results = %+v, want duplicate then created", out.Results)
164		}
165	
166		assertStillSymlink(t, linkPath, targetPath)
167		data, err := os.ReadFile(targetPath)
168		if err != nil {
169			t.Fatal(err)
170		}
171		var stored struct {
172			Batches []struct {
173				Batch string `json:"batch"`
174			} `json:"batches"`
175		}
176		if err := json.Unmarshal(data, &stored); err != nil {
177			t.Fatal(err)
178		}
179		if len(stored.Batches) != 2 || stored.Batches[0].Batch != "B1" || stored.Batches[1].Batch != "B2" {
180			t.Fatalf("linked registry = %s, want B1 then B2", data)
181		}
182	}
183	
184	// Confirming an already-registered batch through a link stays a pure
185	// duplicate: the success JSON says "duplicate", and the linked registry's
186	// bytes and modification time are exactly as before.
187	func TestBatchRegisterDuplicateThroughSymlinkLeavesTargetUntouched(t *testing.T) {
188		root := t.TempDir()
189		targetPath := filepath.Join(root, "real.json")
190		linkPath := filepath.Join(root, "link.json")
191		const content = `{"version":1,"batches":[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}]}`
192		setupLinkedCLIRegistry(t, targetPath, linkPath, targetPath, content, 0o644)
193		pinned := time.Date(2002, time.March, 4, 5, 6, 7, 0, time.UTC)
194		if err := os.Chtimes(targetPath, pinned, pinned); err != nil {
195			t.Fatal(err)
196		}
197	
198		var stdout bytes.Buffer
199		err := runBatchRegister([]string{
200			"--registry", linkPath,
201			"--batch", "B1", "--product", "P", "--quantity", "1", "--unit", "kg",
202		}, &stdout)
203		if err != nil {
204			t.Fatalf("confirming a duplicate through the link must succeed: %v", err)
205		}
206		var out struct {
207			Status string `json:"status"`
208		}
209		if err := json.Unmarshal(bytes.TrimSpace(stdout.Bytes()), &out); err != nil {
210			t.Fatalf("stdout is not the expected JSON: %v (%q)", err, stdout.String())
211		}
212		if out.Status != "duplicate" {
213			t.Fatalf("status = %q, want duplicate", out.Status)
214		}
215	
216		info, err := os.Stat(targetPath)
217		if err != nil {
218			t.Fatal(err)
219		}
220		if !info.ModTime().Equal(pinned) {
221			t.Errorf("duplicate confirmation touched the target's modification time: got %v, want %v", info.ModTime(), pinned)
222		}
223		data, err := os.ReadFile(targetPath)
224		if err != nil {
225			t.Fatal(err)
226		}
227		if string(data) != content {
228			t.Errorf("duplicate confirmation changed the target bytes:\nbefore %s\nafter  %s", content, data)
229		}
230		assertStillSymlink(t, linkPath, targetPath)
