245						}
246					}
247					// The request is legal and conflict-free (proven by the success
248					// controls below); the failure wording must never masquerade as
249					// invalid input or a batch conflict.
250					for _, mustNot := range []string{
251						"usage:", "missing required flag", "invalid --",
