input.old_string:
// resolveRegistryTarget returns the file a save to path must actually
// replace. When path is a symbolic link, the link is followed to its target
// — an absolute target, or a relative one resolved against the link's own
// directory, never against the process working directory — so the save
// updates the file the user sees through the link instead of replacing the
// link with a regular file. A dangling link or a link loop is an error: the
// save must not create the target or overwrite the link as if this were a
// first registration. A non-link path (existing or not) is returned
// unchanged.
func resolveRegistryTarget(path string) (string, error) {
	info, err := os.Lstat(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return path, nil
		}
		return "", fmt.Errorf("cannot inspect registry path: %w", err)
	}
	if info.Mode()&os.ModeSymlink == 0 {
		return path, nil
	}
	target, err := filepath.EvalSymlinks(path)
	if err != nil {
		return "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", err)
	}
	return target, nil
}

input.new_string:
// resolveRegistryTarget returns the file a save to path must actually
// replace, together with the directory the atomic save must prepare its
// temporary file in — the physical directory holding target, with every
// symbolic link in path's ancestry and every ".." resolved by the kernel's
// rules rather than as plain text.
//
// The link-aware resolution matters whenever an ancestor directory is a
// symbolic link. filepath operations such as filepath.Dir followed by
// CreateTemp fold ".." lexically: given work/alias -> store/child,
// "work/alias/../batches.json" collapses to "work/batches.json" even though
// the file the user reads is store/batches.json. Resolving the existing
// target directory through the kernel makes the save land in the exact file
// Load read and lets it succeed with write permission on that one directory
// alone — the directory named in the user's path (e.g. work) never needs to
// be writable, and a sibling file that merely shares the lexical spelling
// (work/batches.json) is never created or replaced.
//
// When the file itself is a symbolic link, the link is followed to its
// target — an absolute target, or a relative one resolved against the link's
// own directory, never against the process working directory — so the save
// updates the file the user sees through the link instead of replacing the
// link with a regular file. When the path does not exist yet, its longest
// existing ancestor directory is resolved the same way and the missing tail
// is reattached verbatim; the first save then creates only that file. A
// dangling link, a chain of links forming a loop, or any other unresolvable
// component is an error: the save must not create the target, overwrite the
// link, or write into the lexical ".." sibling directory as if this were a
// first registration.
func resolveRegistryTarget(path string) (target, dir string, err error) {
	dir, base := filepath.Split(filepath.Clean(path))
	resolvedDir, derr := filepath.EvalSymlinks(strings.TrimSuffix(dir, string(filepath.Separator)))
	if derr != nil {
		return "", "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", derr)
	}
	target = filepath.Join(resolvedDir, base)
	// When the registry file exists, EvalSymlinks on the full path also
	// follows a link in the final component: a save addressed at a link
	// replaces the linked file, never the link itself. A not-exist error for
	// the computed file is fine for both shapes — a genuinely new file, or a
	// dangling final link — and the dangling-link distinction is reported by
	// the Lstat check below.
	resolvedPath, perr := filepath.EvalSymlinks(target)
	switch {
	case perr == nil:
		target = resolvedPath
	case errors.Is(perr, fs.ErrNotExist):
		// A dangling final symbolic link also reports "not exist", but the
		// path is occupied: keep rejecting it instead of creating the target.
		if info, lerr := os.Lstat(target); lerr == nil && info.Mode()&os.ModeSymlink != 0 {
			return "", "", fmt.Errorf("registry path is a symbolic link whose target does not exist: %w", perr)
		}
	default:
		return "", "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", perr)
	}
	return target, filepath.Dir(target), nil
}

