			return resolved, filepath.Dir(resolved), nil
		}
	} else if !errors.Is(lerr, fs.ErrNotExist) {
		return "", "", fmt.Errorf("cannot inspect registry path: %w", lerr)
	}

	// Split on the final separator without cleaning: a ".." immediately after
	// a symlinked directory must be resolved by the kernel, not folded
	// lexically into the link's sibling.
	parent, base := filepath.Split(path)
	parent = strings.TrimSuffix(parent, string(filepath.Separator))
	if parent == "" {
		parent = "."
	}

	// Strip unresolvable tail segments up to the longest existing ancestor.
	// Lstat resolves ".." the way the kernel does, so a missing component
	// past a symlinked directory is removed without ever collapsing the link;
	// stripped segments are reattached verbatim once the real ancestor is
	// known, so first registrations can still create nested directories.
	existing := parent
	var missing []string
	for {
		if _, lerr := os.Lstat(existing); lerr == nil {
			break
		} else if !errors.Is(lerr, fs.ErrNotExist) {
			return "", "", fmt.Errorf("cannot inspect registry path: %w", lerr)
		}
		upper, seg := filepath.Split(existing)
		if seg == "" {
			break // reached a filesystem root
		}
		existing = strings.TrimSuffix(upper, string(filepath.Separator))
		if existing == "" {
			existing = string(filepath.Separator)
		}
		missing = append([]string{seg}, missing...)
	}

	// Resolve every link in the existing ancestry. This is what turns
	// "work/alias/.." (alias -> store/child) into store rather than work.
	resolvedAncestor, rerr := filepath.EvalSymlinks(existing)
	if rerr != nil {
		// A dangling link or a link loop in the ancestry: never treat this
		// as a first registration.
		return "", "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", rerr)
	}
	physDir := filepath.Clean(filepath.Join(resolvedAncestor, filepath.Join(missing...)))
	lexDir := filepath.Dir(filepath.Clean(path))

