	// directory: if the reassembled directory cannot even be stated, a
	// dangling link is hiding in that tail (e.g. work/bad-link/.. where
	// bad-link dangles). Reject it instead of preparing a temporary file at a
	// path the kernel can never resolve. The check path is concatenated
	// without cleaning so the dangling component survives — filepath.Join
	// would fold "bad-link/.." away. Plain missing tail directories without a
	// ".." (a genuine first registration) are left for MkdirAll to create.
	if slices.Contains(missing, "..") {
