		for _, seg := range missing {
			checkPath += string(filepath.Separator) + seg
		}
		if _, err := os.Stat(checkPath); err != nil {
			return "", "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", err)
		}
