	// actually crossed (plain paths then keep their exact legacy spelling),
	// where the crossed path physically ends up, and whether a dangling link
	// or an unresolvable ".." hides in the middle.
	anchor, missing := longestExistingAncestor(parent)
	cur := anchor
	crossedLink := false
	var unvalidatedTail []string
	for i, seg := range missing {
		next := cur + string(filepath.Separator) + seg
		if seg == ".." {
			// Reaching a ".." requires every component before it to resolve.
			// A failure here means a dangling link is hiding in the walk.
			if _, e := os.Stat(next); e != nil {
				return "", "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", e)
			}
			cur = next
			continue
		}
		li, e := os.Lstat(next)
		switch {
		case e == nil:
			if li.Mode()&os.ModeSymlink != 0 {
				crossedLink = true
				if _, f := os.Stat(next); f != nil {
